INSERT INTO abilities (name, description, owner_id) VALUES
('Jajanken', 'Golpe inspirado no pedra-papel-tesoura: pedra é um soco de Intensificação, tesoura uma lâmina de Transmutação e papel um disparo de Emissão', (SELECT id FROM characters WHERE first_name = 'Gon' AND last_name = 'Freecss')),
('Transformação por Restrição', 'Por um juramento feito em desespero, Gon envelhece até a idade capaz de vencer Neferpitou e libera todo o seu potencial', (SELECT id FROM characters WHERE first_name = 'Gon' AND last_name = 'Freecss')),
('Palma Relâmpago', 'Eletrocuta o alvo ao tocá-lo com as duas palmas', (SELECT id FROM characters WHERE first_name = 'Killua' AND last_name = 'Zoldyck')),
('Raio', 'Salta sobre o alvo e dispara um raio pelos dedos, paralisando-o por alguns instantes', (SELECT id FROM characters WHERE first_name = 'Killua' AND last_name = 'Zoldyck')),
('Velocidade Divina', 'Carrega o corpo de eletricidade para reagir sozinho a estímulos e se mover na velocidade do raio', (SELECT id FROM characters WHERE first_name = 'Killua' AND last_name = 'Zoldyck')),
('Eco Rítmico', 'Técnica de assassino: passos em ritmo variado criam imagens residuais para confundir o adversário', (SELECT id FROM characters WHERE first_name = 'Killua' AND last_name = 'Zoldyck')),
('Corrente da Cura', 'Corrente do polegar com uma cruz na ponta que cura ferimentos usando Intensificação', (SELECT id FROM characters WHERE first_name = 'Kurapika' AND last_name IS NULL)),
('Corrente Rabdomante', 'Corrente do anelar com um peso na ponta, usada como pêndulo para encontrar pessoas e detectar mentiras', (SELECT id FROM characters WHERE first_name = 'Kurapika' AND last_name IS NULL)),
('Corrente Prisão', 'Corrente do dedo médio que prende o alvo e o força ao estado de Zetsu, anulando o seu Nen', (SELECT id FROM characters WHERE first_name = 'Kurapika' AND last_name IS NULL)),
('Corrente do Julgamento', 'Corrente do mínimo que crava uma lâmina no coração do alvo e impõe uma regra; quebrá-la mata o alvo', (SELECT id FROM characters WHERE first_name = 'Kurapika' AND last_name IS NULL)),
('Corrente Ladra', 'Corrente do indicador com ponta de seringa que drena a aura do alvo e rouba uma habilidade de Nen', (SELECT id FROM characters WHERE first_name = 'Kurapika' AND last_name IS NULL)),
('Tempo do Imperador', 'Ao ativar os olhos escarlates, vira especialista e usa as seis categorias com 100% de eficiência', (SELECT id FROM characters WHERE first_name = 'Kurapika' AND last_name IS NULL)),
('Soco Remoto', 'Golpeia uma superfície e emite a aura por ela até um portal, de onde sai um soco no alvo à distância', (SELECT id FROM characters WHERE first_name = 'Leorio' AND last_name = 'Paradinight')),
('Bungee Gum', 'Dá à aura as propriedades da borracha e do chiclete: estica, encolhe e gruda', (SELECT id FROM characters WHERE first_name = 'Hisoka' AND last_name = 'Morow')),
('Textura Surpresa', 'Aplica aura numa superfície lisa, como papel ou pano, para mudar a aparência dela e enganar', (SELECT id FROM characters WHERE first_name = 'Hisoka' AND last_name = 'Morow')),
('Alteração Corporal', 'Agulhas cravadas no próprio corpo mudam o rosto, o corpo e a cor da pele', (SELECT id FROM characters WHERE first_name = 'Illumi' AND last_name = 'Zoldyck')),
('Feitiço Hipnótico', 'Uma agulha no cérebro do alvo o condiciona a seguir ordens prévias', (SELECT id FROM characters WHERE first_name = 'Illumi' AND last_name = 'Zoldyck')),
('Controle de Cadáveres', 'Agulhas cravadas na cabeça de mortos permitem controlá-los, até para falar e dirigir', (SELECT id FROM characters WHERE first_name = 'Illumi' AND last_name = 'Zoldyck')),
('Pessoas-Agulha', 'Uma agulha carregada de aura no crânio tira a consciência do alvo, que cumpre uma ordem até morrer', (SELECT id FROM characters WHERE first_name = 'Illumi' AND last_name = 'Zoldyck')),
('Caçador de Habilidades', 'Rouba habilidades de Nen e as guarda no livro Segredo do Ladrão; usa uma de cada vez, com o livro aberto', (SELECT id FROM characters WHERE first_name = 'Chrollo' AND last_name = 'Lucilfer')),
('Pano Fun Fun', 'Habilidade roubada de Owl: um pano que encolhe o que cobrir, até um carro', (SELECT id FROM characters WHERE first_name = 'Chrollo' AND last_name = 'Lucilfer')),
('Bodhisattva Guanyin de Cem Formas', 'Invoca atrás de si uma estátua gigante de Guanyin com muitos braços, que golpeia quando Netero junta as mãos em prece', (SELECT id FROM characters WHERE first_name = 'Isaac' AND last_name = 'Netero')),
('Doutor Blythe', 'Boneco gigante materializado que opera e cura ferimentos graves', (SELECT id FROM characters WHERE first_name = 'Neferpitou' AND last_name IS NULL)),
('Marionetista', 'Prende um marionete ao alvo e o controla por completo, até fazê-lo falar e usar Nen', (SELECT id FROM characters WHERE first_name = 'Neferpitou' AND last_name IS NULL)),
('Terpsichora', 'Bailarina monstruosa ligada ao corpo de Neferpitou por fios, que o move como uma marionete em combate', (SELECT id FROM characters WHERE first_name = 'Neferpitou' AND last_name IS NULL));
