INSERT INTO items (name, description, is_nen, owner_id, conjured_by_id) VALUES
('Vara de Pescar', 'Vara de pesca telescópica que Gon usa como arma desde o Exame Hunter', FALSE, (SELECT id FROM characters WHERE first_name = 'Gon' AND last_name = 'Freecss'), NULL),
('Skate', 'Skate amarelo que Killua levou ao seu primeiro Exame Hunter', FALSE, (SELECT id FROM characters WHERE first_name = 'Killua' AND last_name = 'Zoldyck'), NULL),
('Ioiôs', 'Dois ioiôs de liga metálica de 50 kg cada, presente de Milluki', FALSE, (SELECT id FROM characters WHERE first_name = 'Killua' AND last_name = 'Zoldyck'), NULL),
('Colar do Paladino', 'Carta de Greed Island que vira um colar e anula maldições', TRUE, (SELECT id FROM characters WHERE first_name = 'Killua' AND last_name = 'Zoldyck'), NULL),
('Corrente do Polegar', 'Corrente com uma cruz na ponta, ligada ao polegar direito', TRUE, (SELECT id FROM characters WHERE first_name = 'Kurapika' AND last_name IS NULL), (SELECT id FROM abilities WHERE name = 'Corrente da Cura')),
('Corrente do Indicador', 'Corrente com ponta de seringa, ligada ao indicador direito', TRUE, (SELECT id FROM characters WHERE first_name = 'Kurapika' AND last_name IS NULL), (SELECT id FROM abilities WHERE name = 'Corrente Ladra')),
('Corrente do Médio', 'Corrente com um gancho na ponta, ligada ao dedo médio direito', TRUE, (SELECT id FROM characters WHERE first_name = 'Kurapika' AND last_name IS NULL), (SELECT id FROM abilities WHERE name = 'Corrente Prisão')),
('Corrente do Anelar', 'Corrente com um peso em forma de bola, ligada ao anelar direito', TRUE, (SELECT id FROM characters WHERE first_name = 'Kurapika' AND last_name IS NULL), (SELECT id FROM abilities WHERE name = 'Corrente Rabdomante')),
('Corrente do Mínimo', 'Corrente com uma lâmina na ponta, ligada ao mínimo direito', TRUE, (SELECT id FROM characters WHERE first_name = 'Kurapika' AND last_name IS NULL), (SELECT id FROM abilities WHERE name = 'Corrente do Julgamento')),
('Espadas de Madeira', 'Par de bokken que Kurapika usa no Exame Hunter', FALSE, (SELECT id FROM characters WHERE first_name = 'Kurapika' AND last_name IS NULL), NULL),
('Canivete', 'Canivete que Leorio carrega desde o Exame Hunter', FALSE, (SELECT id FROM characters WHERE first_name = 'Leorio' AND last_name = 'Paradinight'), NULL),
('Cartas de Baralho', 'Cartas comuns que Hisoka reforça com aura e usa como lâminas', FALSE, (SELECT id FROM characters WHERE first_name = 'Hisoka' AND last_name = 'Morow'), NULL),
('Agulhas', 'Agulhas de cabeça redonda que Illumi usa em todas as suas habilidades', FALSE, (SELECT id FROM characters WHERE first_name = 'Illumi' AND last_name = 'Zoldyck'), NULL),
('Segredo do Ladrão', 'Livro materializado que guarda as habilidades roubadas, uma por página', TRUE, (SELECT id FROM characters WHERE first_name = 'Chrollo' AND last_name = 'Lucilfer'), (SELECT id FROM abilities WHERE name = 'Caçador de Habilidades')),
('Camisa do Coração', 'Camisa com o kanji 心 (coração) que Netero veste quando luta a sério', FALSE, (SELECT id FROM characters WHERE first_name = 'Isaac' AND last_name = 'Netero'), NULL);
