INSERT INTO nen_categories (name, description) VALUES
('Intensificação', 'Fortalece o corpo e objetos com aura, inclusive a cura.'),
('Transmutação', 'Muda as propriedades da aura (ex.: eletricidade, elasticidade).'),
('Materialização', 'Cria objetos físicos a partir de aura.'),
('Especialização', 'Qualquer habilidade que não se encaixa nas outras categorias.'),
('Manipulação', 'Controla pessoas ou objetos com aura.'),
('Emissão', 'Separa a aura do corpo e a dispara.');
INSERT INTO nen_conditions (description, type, nen_ability_id) VALUES
('Recitar o canto do pedra-papel-tesoura antes do golpe', 'Gatilho', (SELECT id FROM abilities WHERE name = 'Jajanken')),
('Concentrar a aura leva tempo e deixa a guarda aberta', 'Restrição', (SELECT id FROM abilities WHERE name = 'Jajanken')),
('Entrega todo o potencial de Nen em troca do poder imediato', 'Custo', (SELECT id FROM abilities WHERE name = 'Transformação por Restrição')),
('Tocar o alvo com as duas palmas', 'Gatilho', (SELECT id FROM abilities WHERE name = 'Palma Relâmpago')),
('Gasta a eletricidade acumulada, que precisa ser recarregada', 'Custo', (SELECT id FROM abilities WHERE name = 'Velocidade Divina')),
('Cura ferimentos graves só com os olhos escarlates', 'Restrição', (SELECT id FROM abilities WHERE name = 'Corrente da Cura')),
('Só pode ser usada contra membros da Trupe Fantasma; em outro alvo, Kurapika morre', 'Juramento', (SELECT id FROM abilities WHERE name = 'Corrente Prisão')),
('Só com os olhos escarlates ativos', 'Gatilho', (SELECT id FROM abilities WHERE name = 'Tempo do Imperador')),
('Cada segundo de uso custa uma hora de vida', 'Custo', (SELECT id FROM abilities WHERE name = 'Tempo do Imperador')),
('Golpear uma superfície próxima para abrir o portal', 'Gatilho', (SELECT id FROM abilities WHERE name = 'Soco Remoto')),
('Um toque revela a textura falsa', 'Restrição', (SELECT id FROM abilities WHERE name = 'Textura Surpresa')),
('As agulhas ficam no corpo; tirá-las desfaz a mudança', 'Restrição', (SELECT id FROM abilities WHERE name = 'Alteração Corporal')),
('A agulha precisa ficar cravada no cérebro do alvo', 'Restrição', (SELECT id FROM abilities WHERE name = 'Feitiço Hipnótico')),
('Só funciona em pessoas mortas', 'Restrição', (SELECT id FROM abilities WHERE name = 'Controle de Cadáveres')),
('Cravar várias agulhas na cabeça', 'Gatilho', (SELECT id FROM abilities WHERE name = 'Controle de Cadáveres')),
('Cravar no crânio uma agulha carregada de aura', 'Gatilho', (SELECT id FROM abilities WHERE name = 'Pessoas-Agulha')),
('Ver a habilidade sendo usada', 'Restrição', (SELECT id FROM abilities WHERE name = 'Caçador de Habilidades')),
('Fazer perguntas sobre a habilidade e ouvir a resposta', 'Restrição', (SELECT id FROM abilities WHERE name = 'Caçador de Habilidades')),
('O dono põe a mão na capa do livro', 'Restrição', (SELECT id FROM abilities WHERE name = 'Caçador de Habilidades')),
('Cumprir as três condições em até uma hora', 'Restrição', (SELECT id FROM abilities WHERE name = 'Caçador de Habilidades')),
('Juntar as mãos em prece antes de cada golpe', 'Gatilho', (SELECT id FROM abilities WHERE name = 'Bodhisattva Guanyin de Cem Formas')),
('Neferpitou não pode se afastar enquanto o boneco opera', 'Restrição', (SELECT id FROM abilities WHERE name = 'Doutor Blythe')),
('Prender o marionete ao alvo', 'Gatilho', (SELECT id FROM abilities WHERE name = 'Marionetista'));
